        for c in range(w):
            if grid[r][c]:
                tracks.setdefault(c - r, Counter())[grid[r][c]] += 1

    colors = {d: counts.most_common(1)[0][0] for d, counts in tracks.items()}
    ds = sorted(colors)

    # The repeating diagonal motif follows the track order and its band
    # multiplicities (the two adjacent 3 tracks are retained).
    motif = [colors[d] for d in ds]
    if not motif:
        return [row[:] for row in grid]

    # Use a period spanning the marked tracks, then repeat those colors
    # at their corresponding offsets.
    lo, hi = ds[0], ds[-1]
    period = hi - lo + 1
    seq = [None] * period
    for d, color in colors.items():
        seq[d - lo] = color

    # Fill unmarked slots by propagating the preceding band color.
    last = seq[0]
    for i in range(period):
        if seq[i] is None:
            seq[i] = last
        else:
            last = seq[i]

    return [[seq[(c - r - lo) % period] for c in range(w)]
            for r in range(h)]
